package ro.whistlab.core;
import java.util.*;import java.lang.reflect.*;import org.junit.Test;
public class BidEvidenceTest {
 private static Card card(Suit suit,int rank){return new Card(suit,rank);}
 private static MonteCarloAi.View view(boolean observed){return new MonteCarloAi.View(GameMode.ROMANIAN_WHIST,Trump.SPADES,1,3,2,List.of(card(Suit.CLUBS,7),card(Suit.CLUBS,8)),List.of(new MonteCarloAi.Seat(2,observed?Integer.valueOf(2):null,0),new MonteCarloAi.Seat(2,null,0),new MonteCarloAi.Seat(2,null,0),new MonteCarloAi.Seat(2,null,0)),List.of(),List.of(),card(Suit.SPADES,11),true,10);}
 private static List<List<Card>> world(){return List.of(List.of(card(Suit.SPADES,14),card(Suit.SPADES,13)),List.of(card(Suit.CLUBS,7),card(Suit.CLUBS,8)),List.of(card(Suit.HEARTS,7),card(Suit.HEARTS,8)),List.of(card(Suit.CLUBS,9),card(Suit.CLUBS,10)));}
 private static double independent(MonteCarloAi.View v,List<List<Card>> world)throws Exception{var weight=Class.forName("ro.whistlab.coach.BidEvidence").getDeclaredMethod("weight",ro.whistlab.coach.IndependentPlayer.Position.class,List.class);weight.setAccessible(true);return (double)weight.invoke(null,LostGameContractRegressionTest.independent(v),world.stream().map(h->h.stream().map(PublicEndgameOracle::id).toList()).toList());}
 private static Map<String,Object> context(MonteCarloAi.View v){var c=new LinkedHashMap<String,Object>();c.put("purpose","Use already observed bids as soft evidence, not a declaration of future bids or certainty about hidden cards");c.put("rule","Each observed opponent contributes 0.25 + 0.75/(1 + squared bid residual). No declared opponent bid means weight 1. Every feasible hypothetical deal retains positive weight.");c.put("scope","Heuristic likelihood component, not a proof of the best bid. Paired new-game progression remains a separate mandatory gate.");c.put("before",v);return c;}
 @Test public void observedHighBidFavorsACompatibleStrongWorldWithoutEliminatingTheWeakWorld()throws Exception{var v=view(true);var strong=world();var weak=new ArrayList<>(strong);Collections.swap(weak,0,2);var context=context(v);context.put("hypotheticalStrongDeal",strong);context.put("hypotheticalWeakDeal",weak);CapturedRegression.run("bid-evidence-observed",getClass().getName(),"observedHighBidFavorsACompatibleStrongWorldWithoutEliminatingTheWeakWorld",context,c->{c.equal("Observed bid 2 with ace/king of trump has unit weight",1.0,BidEvidence.weight(v,strong));c.equal("Weak two-card world is downweighted, never excluded",0.4,BidEvidence.weight(v,weak));c.equal("Independent implementation has identical observed-evidence semantics",BidEvidence.weight(v,weak),independent(v,weak));});}
 @Test public void absentPublicBidsAreNeutral()throws Exception{var v=view(false);CapturedRegression.run("bid-evidence-neutral",getClass().getName(),"absentPublicBidsAreNeutral",context(v),c->{c.equal("Expert cannot infer a bid that has not been declared",1.0,BidEvidence.weight(v,world()));c.equal("Independent player also leaves undeclared bids neutral",1.0,independent(v,world()));});}
 @Test public void originalHandIsRecoveredFromPublicPlaysWithoutCountingTheCurrentTrickTwice()throws Exception{var original=view(true);var seats=new ArrayList<>(original.seats());seats.set(0,new MonteCarloAi.Seat(1,2,0));var play=new PlayedCard(0,card(Suit.SPADES,14));var v=new MonteCarloAi.View(original.mode(),original.trump(),1,3,2,original.hand(),seats,List.of(play),List.of(play),original.turnedCard(),true,10);var current=new ArrayList<>(world());current.set(0,List.of(card(Suit.SPADES,13)));var context=context(v);context.put("hypotheticalRemainingDeal",current);CapturedRegression.run("bid-evidence-history",getClass().getName(),"originalHandIsRecoveredFromPublicPlaysWithoutCountingTheCurrentTrickTwice",context,c->{c.equal("Played ace plus held king reconstructs the original two-card hand exactly once",1.0,BidEvidence.weight(v,current));c.equal("Independent reconstruction agrees",1.0,independent(v,current));});}
 @Test public void oneCardAndUnsupportedPlayerCountsKeepTheAcceptedNeutralPath()throws Exception{var source=view(true);var one=new MonteCarloAi.View(source.mode(),source.trump(),1,3,1,List.of(card(Suit.CLUBS,7)),source.seats(),List.of(),List.of(),source.turnedCard(),true,10);var three=new MonteCarloAi.View(source.mode(),source.trump(),1,2,2,source.hand(),source.seats().subList(0,3),List.of(),List.of(),source.turnedCard(),true,10);CapturedRegression.run("bid-evidence-domain",getClass().getName(),"oneCardAndUnsupportedPlayerCountsKeepTheAcceptedNeutralPath",context(source),c->{c.equal("Expert one-card policy is not calibrated by this model",1.0,BidEvidence.weight(one,world()));c.equal("Independent one-card policy is unchanged",1.0,independent(one,world()));c.equal("Three-player positions stay outside the fitted domain",1.0,BidEvidence.weight(three,world().subList(0,3)));c.equal("Independent domain guard matches",1.0,independent(three,world().subList(0,3)));});}
}
